def shift_capacity(loads, shifts):
    if len(loads) == 0:
        return 0
    if shifts < 1:
        return -1
    low = 0
    high = 0
    for weight in loads:
        high += weight
        if weight > low:
            low = weight
    while low < high:
        cap = (low + high) // 2
        used = 1
        carried = 0
        for weight in loads:
            if carried + weight > cap:
                used += 1
                carried = 0
            carried += weight
        if used > shifts:
            low = cap + 1
        else:
            high = cap
    return low

